/** Icons an admin can pick for a category. */
function category_icon_names(): array
{
    return ['tag', 'car', 'building', 'home', 'smartphone', 'laptop', 'sofa', 'shirt', 'briefcase', 'wrench', 'paw',
        'bike', 'dumbbell', 'book', 'baby', 'gamepad', 'music', 'camera', 'package', 'store', 'heart', 'zap', 'globe'];
}

function icon(string $name, string $class = ''): string
{
    return '<svg class="ic' . ($class !== '' ? ' ' . $class : '') . '" aria-hidden="true"><use href="#i-' . $name . '"/></svg>';
}

function icon_sprite(): string
{
    $out = '<svg xmlns="http://www.w3.org/2000/svg" style="display:none">';
    foreach (icon_defs() as $name => $paths) {
        $out .= '<symbol id="i-' . $name . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">' . $paths . '</symbol>';
    }
    return $out . '</svg>';
}
